import { useEffect, useState } from "react";
import LeaveService from "../Services/LeaveService";

const badge = (status) => ({
    padding: "4px 12px", borderRadius: "20px", fontSize: "11px", fontWeight: "700",
    letterSpacing: "0.6px", textTransform: "uppercase", color: "#fff",
    background: status === "APPROVED" ? "#22c55e" : status === "REJECTED" ? "#ef4444" : "#f59e0b"
});

const statCard = (label, count, color, icon) => (
    <div key={label} style={{ background: "#fff", borderRadius: "12px", padding: "20px 28px", minWidth: "140px", boxShadow: "0 2px 12px rgba(0,0,0,0.07)", borderTop: `4px solid ${color}`, display: "flex", alignItems: "center", gap: "14px" }}>
        <span style={{ fontSize: "28px" }}>{icon}</span>
        <div>
            <div style={{ fontSize: "26px", fontWeight: "800", color, lineHeight: 1 }}>{count}</div>
            <div style={{ fontSize: "12px", color: "#6b7280", fontWeight: "600", marginTop: "4px" }}>{label}</div>
        </div>
    </div>
);

const ViewLeaves = () => {
    const [leaves, setLeaves] = useState([]);

    useEffect(() => {
        LeaveService.getLeaves().then(res => setLeaves(res.data)).catch(err => console.log(err));
    }, []);

    const updateStatus = (id, status) => {
        LeaveService.updateLeaveStatus(id, status).then(() =>
            setLeaves(leaves.map(l => l.lid === id ? { ...l, status } : l))
        );
    };

    const count = (s) => leaves.filter(l => l.status === s).length;

    return (
        <div style={{ padding: "36px", background: "#f4f5f7", minHeight: "100vh", fontFamily: "'DM Sans', sans-serif" }}>

            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "28px" }}>
                <div>
                    <h3 style={{ fontWeight: "800", fontSize: "22px", margin: 0, color: "#1a1c1e" }}>📋 Leave Requests</h3>
                    <p style={{ margin: 0, color: "#6b7280", fontSize: "13px" }}>{leaves.length} total requests</p>
                </div>
                <div style={{ display: "flex", gap: "14px" }}>
                    {statCard("Pending", count("PENDING"), "#f59e0b", "⏳")}
                    {statCard("Approved", count("APPROVED"), "#22c55e", "✅")}
                    {statCard("Rejected", count("REJECTED"), "#ef4444", "❌")}
                </div>
            </div>

            <div style={{ background: "#fff", borderRadius: "12px", boxShadow: "0 2px 12px rgba(0,0,0,0.07)", overflow: "hidden" }}>
                <table style={{ width: "100%", borderCollapse: "collapse" }}>
                    <thead>
                        <tr style={{ background: "#414447", color: "#fff" }}>
                            {["#", "Employee ID", "Leave Type", "Start Date", "End Date", "Status", "Action"].map(h => (
                                <th key={h} style={{ padding: "14px 18px", fontWeight: "600", fontSize: "13px", textAlign: "left", letterSpacing: "0.4px" }}>{h}</th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {leaves.map((leave, i) => (
                            <tr key={leave.lid} style={{ borderBottom: "1px solid #f1f1f1", transition: "background 0.15s" }}
                                onMouseEnter={e => e.currentTarget.style.background = "#fafafa"}
                                onMouseLeave={e => e.currentTarget.style.background = "#fff"}>
                                <td style={{ padding: "14px 18px", color: "#9ca3af", fontSize: "13px" }}>{i + 1}</td>
                                <td style={{ padding: "14px 18px", fontWeight: "600", fontSize: "14px" }}>{leave.employee?.id}</td>
                                <td style={{ padding: "14px 18px", fontSize: "14px" }}>{leave.leaveType}</td>
                                <td style={{ padding: "14px 18px", fontSize: "13px", color: "#4b5563" }}>{leave.startDate}</td>
                                <td style={{ padding: "14px 18px", fontSize: "13px", color: "#4b5563" }}>{leave.endDate}</td>
                                <td style={{ padding: "14px 18px" }}>
                                    <span style={badge(leave.status)}>{leave.status}</span>
                                </td>
                                <td style={{ padding: "14px 18px" }}>
                                    {leave.status === "PENDING" ? (
                                        <div style={{ display: "flex", gap: "8px" }}>
                                            <button onClick={() => updateStatus(leave.lid, "APPROVED")}
                                                style={{ background: "#22c55e", border: "none", borderRadius: "8px", color: "#fff", padding: "7px 16px", fontWeight: "600", fontSize: "13px", cursor: "pointer", display: "flex", alignItems: "center", gap: "6px" }}>
                                                ✓ Approve
                                            </button>
                                            <button onClick={() => updateStatus(leave.lid, "REJECTED")}
                                                style={{ background: "#ef4444", border: "none", borderRadius: "8px", color: "#fff", padding: "7px 16px", fontWeight: "600", fontSize: "13px", cursor: "pointer", display: "flex", alignItems: "center", gap: "6px" }}>
                                                ✕ Reject
                                            </button>
                                        </div>
                                    ) : (
                                        <span style={{ color: "#9ca3af", fontSize: "13px" }}>Action Completed</span>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ViewLeaves;
